function Row([string]$n, [string]$topic, [string]$ans, [string]$src) {
    $st = if ([string]::IsNullOrWhiteSpace($ans)) { '⬜' } else { '✅' }
    if ([string]::IsNullOrWhiteSpace($ans)) { $ans = '_(ถาม SA)_' }
    return "| $n | $topic | $ans | $src | $st |"
}
$rows = @(
