$($rows -join "`n")
"@
Install-ProjectFile 'status/INTAKE.md' $intake

# ---------------------------------------------------------------------------
# 5. Patch ไฟล์ของ kit
# ---------------------------------------------------------------------------
Write-Section '🔧 Patching kit files (มี marker = ข้าม)'
Update-ProjectFile 'CLAUDE.md' '## 0. Workflow หลัก' {
    param($t)
    $i = $t.IndexOf('## 1. ')
    if ($i -lt 0) { return $t.TrimEnd() + "`n`n" + $T_Claude0 }
    return $t.Substring(0, $i) + $T_Claude0 + $t.Substring($i)
}
Update-ProjectFile '.claude/commands/next-step.md' 'knowledge/WORKFLOW.md' {
    param($t)
    $line = '7. ลำดับขั้นของงานยึด `knowledge/WORKFLOW.md` (คู่มือใน knowledge/ เป็นแกน + BR / Gap / Decision / Status) — เลือกขั้นถัดไปจากขั้นแรกในตารางที่ยังไม่ผ่าน gate'
    $i = $t.LastIndexOf('$ARGUMENTS')
    if ($i -ge 0) { return $t.Substring(0, $i).TrimEnd() + "`n" + $line + "`n`n" + $t.Substring($i) }
    return $t.TrimEnd() + "`n" + $line + "`n"
}
Update-ProjectFile 'knowledge/glossary.md' 'BR-nn' {
    param($t)
    $t.TrimEnd() + "`n| I# / BR-nn / GAP-nn | คำถาม intake / business rule / gap — ดู ``knowledge/WORKFLOW.md`` §2 |`n| D-R1–D-R9 | กฎแปลง SQL (``knowledge/reference/spark-to-oracle-sql.md``) · ``/sql-check`` ตรวจอัตโนมัติ D-R1–D-R8 |`n"
}
Update-ProjectFile 'status/OPEN_DECISIONS.md' 'Schema qualification' {
    param($t)
    $n = 0
    foreach ($m in [regex]::Matches($t, '###\s*Q(\d+)\.')) { $n = [Math]::Max($n, [int]$m.Groups[1].Value) }
    $t.TrimEnd() + "`n" + $T_Q_Schema.Replace('{{TODAY}}', $Today).Replace('{{N}}', [string]($n + 1))
}

# ---------------------------------------------------------------------------
# Smoke test (scripts/ ของโปรเจกต์)
# ---------------------------------------------------------------------------
Write-Section '🧪 Smoke test'
$script:Smoke = $null
if (-not $script:Python) { Write-Warn 'ข้าม — ไม่มี Python' }
elseif ($DryRun) { Write-Info 'DryRun — ข้าม' }
else {
    $chkScripts = Join-Path $script:Root 'scripts/checks'
    $pyFiles = @(Get-ChildItem -LiteralPath (Join-Path $script:Root 'scripts') -Filter '*.py' -File -Recurse -ErrorAction SilentlyContinue | Where-Object { $_.FullName -notmatch '[\\/]__pycache__[\\/]' })
    $r = Invoke-Py (@('-m', 'py_compile') + @($pyFiles | ForEach-Object { $_.FullName }))
    $okCompile = ($r.Code -eq 0)
    if ($okCompile) { Write-Ok "compile scripts/**/*.py ($($pyFiles.Count) ไฟล์)" } else { Write-Fail 'compile scripts ไม่ผ่าน'; Write-Info (($r.Out -split "`n" | Select-Object -Last 3) -join ' / ') }
    $r1 = Invoke-Py @((Join-Path $chkScripts 'check_sql.py'), '--selftest')
    if ($r1.Code -eq 0) { Write-Ok "check_sql.py --selftest $((($r1.Out -split "`n") | Where-Object { $_ -match 'pass|ok|PASS|OK' } | Select-Object -Last 1))" } else { Write-Fail "check_sql.py --selftest (exit $($r1.Code))" }
    $r2 = Invoke-Py @((Join-Path $chkScripts 'extract_partitions.py'), '--selftest')
    if ($r2.Code -eq 0) { Write-Ok "extract_partitions.py --selftest $((($r2.Out -split "`n") | Where-Object { $_ -match 'pass|ok|PASS|OK' } | Select-Object -Last 1))" } else { Write-Fail "extract_partitions.py --selftest (exit $($r2.Code))" }
    $script:Smoke = ($okCompile -and $r1.Code -eq 0 -and $r2.Code -eq 0)
    if ($script:Smoke) { Write-Ok 'smoke test passed' }
}

# ---------------------------------------------------------------------------
# 6. SQL checks (partitions + check_sql)
# ---------------------------------------------------------------------------
Write-Section '🔬 SQL checks'
$checkSummary = New-Object System.Collections.Generic.List[string]
if (-not $A.runChecks) { Write-Info 'ข้าม (เลือกไม่รันใน Options) — ใช้ /sql-check ภายหลัง' }
elseif (-not $script:Python) { Write-Warn 'ข้าม — ไม่มี Python' }
elseif ($DryRun) { Write-Info 'DryRun — ข้าม extract_partitions / check_sql' }
else {
    $partCsv = Join-Path $script:Root 'config/partitions_check.csv'
    if ((Test-Path $partCsv) -and -not $Force) { Write-Ok 'config/partitions_check.csv มีอยู่แล้ว' }
    elseif ($exportFull -and (Test-Path $exportFull)) {
        if (Test-Path $partCsv) { $null = Backup-File $partCsv }
        $r = Invoke-Py @((Join-Path $script:Root 'scripts/checks/extract_partitions.py'), $exportFull, '-o', $partCsv)
        if ($r.Code -eq 0 -and (Test-Path $partCsv)) {
            $n = @(Get-Content -LiteralPath $partCsv | Select-Object -Skip 1).Count
            Write-Ok "config/partitions_check.csv ($n ตาราง overwrite)"; Add-Report 'create' 'config/partitions_check.csv'
        } else { Write-Warn "extract_partitions.py ไม่สำเร็จ (exit $($r.Code)) — รันเองภายหลัง"; Write-Info ($r.Out -split "`n" | Select-Object -Last 3) }
    } else { Write-Warn 'ไม่พบ export JSON ตาม config — ข้าม partitions_check.csv' }

    $ddlArg = @()
    if ($ddlFiles.Count -eq 1) { $ddlArg = @('--ddl', $ddlFiles[0].FullName) }
    elseif ($ddlFiles.Count -gt 1) { Write-Warn 'input/oracle_ddl มีหลายไฟล์ — ไม่ใส่ --ddl อัตโนมัติ (ใช้ /sql-check เลือกเอง)' }
    $partArg = @(); if (Test-Path $partCsv) { $partArg = @('--partitions', $partCsv) }

    foreach ($pair in @(@('converted', 'output/sql/converted'), @('dml', 'output/dml'))) {
        $dir = Join-Path $script:Root $pair[1]
        if (-not (Test-Path $dir) -or -not (Get-ChildItem -LiteralPath $dir -Filter '*.sql' -File -ErrorAction SilentlyContinue)) {
            Write-Info "$($pair[1]) ยังไม่มี SQL — ข้าม (รัน /sql-check หลัง /convert หรือ /gen-export)"; continue
        }
        $r = Invoke-Py (@((Join-Path $script:Root 'scripts/checks/check_sql.py'), $dir) + $ddlArg + $partArg)
        if ($ddlArg.Count -and $r.Out -match 'cannot read --ddl') {
            Write-Warn "อ่านไฟล์ DDL ไม่ได้ ($(Split-Path -Leaf $ddlArg[1])) — รันใหม่โดยไม่ใส่ --ddl · ไฟล์ต้องเป็น CSV/TSV/JSON ที่มีหัว TABLE_NAME, COLUMN_NAME"
            $ddlArg = @()
            $r = Invoke-Py (@((Join-Path $script:Root 'scripts/checks/check_sql.py'), $dir) + $partArg)
        }
        $outFile = Join-Path $script:Root "output/verify/sql_check_$($pair[0]).txt"
        Save-Text $outFile ("# check_sql.py — $($pair[1]) — $Today`n`n" + $r.Out + "`n")
        $sum = ($r.Out -split "`n" | Where-Object { $_ -match '^checked \d+ file' } | Select-Object -Last 1)
        $byRule = @{}
        foreach ($m in [regex]::Matches($r.Out, '\[(ERROR|WARN)\][^\n]*?\(rule (D-R\d)')) { $k = "$($m.Groups[1].Value) $($m.Groups[2].Value)"; $byRule[$k] = 1 + [int]$byRule[$k] }
        $rules = ($byRule.GetEnumerator() | Sort-Object Name | ForEach-Object { "$($_.Name)=$($_.Value)" }) -join ', '
        Write-Ok "$($pair[1]): $sum"
        if ($rules) { Write-Info "ตามกฎ: $rules" }
        Write-Info "รายงาน: output/verify/sql_check_$($pair[0]).txt"
        $checkSummary.Add("$($pair[0]): $sum$(if ($rules) { " ($rules)" })")
        Add-Report 'create' "output/verify/sql_check_$($pair[0]).txt"
    }
}

