# ---------------------------------------------------------------------------
# Workflow Checklist (คล้าย Pre-flight Checklist ของ kit)
# ---------------------------------------------------------------------------
Write-Section '✅ Workflow Checklist (knowledge + SA governance)'
function Get-FileText([string]$rel) { $p = Join-Path $script:Root $rel; if (Test-Path $p) { return (Read-Text $p) } return '' }
$intakeTxt = Get-FileText 'status/INTAKE.md'
$iDone = ([regex]::Matches($intakeTxt, '(?m)^\| I\d+ \|.*\| ✅[^|]*\|\s*$')).Count
$iAll  = ([regex]::Matches($intakeTxt, '(?m)^\| I\d+ \|')).Count
$pfTxt = Get-FileText 'status/PREFLIGHT_CHECKLIST.md'
$pf = [regex]::Match($pfTxt, 'passed \*\*(\d)/5\*\*')
$odTxt = Get-FileText 'status/OPEN_DECISIONS.md'
$qSec = [regex]::Match($odTxt, '(?s)### Q\d+\. Schema qualification.*?(?=\n### |\n## |\z)')
$qClosed = $qSec.Success -and ($qSec.Value -match '\[[xX]\][^\n]*✅ SA')
$refOk = @(Get-ChildItem -LiteralPath (Join-Path $script:Root 'input/odi_reference') -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.xml', '.zip' }).Count -gt 0
$ddlOk = @(Get-ChildItem -LiteralPath (Join-Path $script:Root 'input/oracle_ddl') -File -ErrorAction SilentlyContinue).Count -gt 0
$overlay = @('knowledge/WORKFLOW.md', 'status/INTAKE.md', 'status/BUSINESS_RULES.md', 'status/GAP_ANALYSIS.md', '.claude/commands/intake.md', '.claude/commands/br-catalog.md', '.claude/commands/gap-analysis.md', '.claude/commands/sql-check.md')
$ovMiss = @($overlay | Where-Object { -not (Test-Path (Join-Path $script:Root $_)) })
$checks = @(
    @{ ok = ((Test-Path (Join-Path $script:Root 'scripts/checks/check_sql.py')) -and (Test-Path (Join-Path $script:Root 'knowledge/reference/migration-rules.md'))); item = 'คู่มือ (knowledge/) + สคริปต์ตรวจ SQL (scripts/checks) อยู่ในโปรเจกต์'; note = $(if ($script:Smoke) { 'smoke test passed' } elseif ($null -eq $script:Smoke) { 'ยังไม่ได้รัน smoke test' } else { 'smoke test ไม่ผ่าน' }) },
    @{ ok = ($ovMiss.Count -eq 0); item = 'Workflow overlay ครบ (WORKFLOW / INTAKE / BR / GAP / 4 commands)'; note = $(if ($ovMiss.Count) { 'ขาด ' + ($ovMiss -join ', ') } else { 'knowledge/WORKFLOW.md' }) },
    @{ ok = ($iAll -gt 0 -and $iDone -eq $iAll); item = "Intake I1–I17 ตอบครบ"; note = "$iDone/$iAll — ที่เหลือ: /intake" },
    @{ ok = $refOk; item = 'Smart Export reference ของ repository ปลายทาง (I2)'; note = 'input/odi_reference/' },
    @{ ok = $ddlOk; item = 'DDL / all_tab_columns สำหรับ check_sql --ddl (I3)'; note = 'input/oracle_ddl/' },
    @{ ok = (Test-Path (Join-Path $script:Root 'config/partitions_check.csv')); item = 'partitions_check.csv (D-R7)'; note = 'config/partitions_check.csv' },
    @{ ok = ($pf.Success -and $pf.Groups[1].Value -eq '5'); item = 'kit PREFLIGHT 5/5 (G0)'; note = $(if ($pf.Success) { "$($pf.Groups[1].Value)/5 — /preflight" } else { 'ไม่พบ status/PREFLIGHT_CHECKLIST.md' }) },
    @{ ok = $qClosed; item = 'Q Schema qualification ปิดแล้ว (D-R2 ↔ kit)'; note = 'status/OPEN_DECISIONS.md — SA ตัดสิน' }
)
$n = 0; $passed = 0
foreach ($c in $checks) {
    $n++
    if ($c.ok) { $passed++; Write-Host ("   ✅ {0}. {1} — {2}" -f $n, $c.item, $c.note) -ForegroundColor Green }
    else { Write-Host ("   ⬜ {0}. {1} — {2}" -f $n, $c.item, $c.note) -ForegroundColor Yellow }
}
Write-Host ''
if ($passed -eq $checks.Count) { Write-Ok "Workflow checklist passed $passed/$($checks.Count)" }
else { Write-Warn "Workflow checklist passed $passed/$($checks.Count) — ข้อ ⬜ ทำต่อใน Claude ตามขั้นถัดไป" }

# ---------------------------------------------------------------------------
# สรุปการส่งมอบ (อ่านก่อนใช้งาน)
# ---------------------------------------------------------------------------
Write-Section '📌 สรุปการส่งมอบ (อ่านก่อนใช้งาน)'
$exTasks = @(Get-Prop $cfg 'scope.excluded_tasks' @())
$ldTab = [string](Get-Prop $cfg 'profile.landing_table' '')
$odiMiss = @(@('logical_schema', 'context_code', 'work_user', 'repository_version', 'odi_version') | Where-Object { -not [string](Get-Prop $cfg "odi.$_" '') })
Write-Host ('   ทาสก์ที่ตัดออก          : ' + $(if ($exTasks.Count) { ($exTasks -join ', ') + '  (เหตุผล: config/config.json scope.excluded_reason)' } else { 'ไม่มี' }))
Write-Host ('   placeholder ที่เหลือ     : ' + $(if ($ldTab) { "ยังไม่ได้ยืนยันว่า $ldTab มีคอลัมน์ partition_minute จริง" } else { 'ไม่มี landing table (เอกสารแสดง <landing table - ยังไม่ระบุ>)' }) + $(if ($odiMiss.Count) { " · ค่า ODI ที่ยังว่าง: $($odiMiss -join ', ') (วาง Smart Export แล้ว /gen-export จะอ่านเอง หรือตั้งใน config/config.json)" } else { '' }))
Write-Host '   Topology ที่ต้องตั้งเอง   : JDBC URL + user/password ของ data server ใน ODI Studio (ไม่มีรหัสผ่านในไฟล์ที่ kit สร้าง) · connection / logical schema / context ถ้า repository ปลายทางยังไม่มี'
Write-Host '   Scenario ที่ต้อง generate : ทุก Procedure / Package หลัง import — kit ไม่สร้าง Scenario ที่ compile แล้ว ให้ generate ใน ODI Studio'
Write-Host '   ยังไม่ได้ยืนยัน           : ไฟล์ ODI XML ที่ generate ออกมา import และรันได้จริงตั้งแต่ต้นจนจบ (kit ตรวจโครงสร้าง ไม่ได้ import ให้)' -ForegroundColor Yellow

# ---------------------------------------------------------------------------
# Next steps
# ---------------------------------------------------------------------------
Write-Section '➡️  Next steps'
$steps = @(
    "cd `"$(Get-DisplayPath $script:Root)`"",
    'claude   (หรือเปิดโฟลเดอร์นี้ใน Claude desktop / Cowork)',
    '/next-step — อ่าน STATUS + knowledge/WORKFLOW.md แล้วเลือกขั้นถัดไป',
    '/preflight — rp00 ให้ SA/DBA รันเก็บหลักฐาน (G0)',
    '/intake — ไล่ข้อ ⬜ ใน status/INTAKE.md ทีละข้อ',
    '/convert -> /br-catalog — Business Rules จาก raw Spark SQL ให้ SA ยืนยัน',
    '/sql-check + /review-sql + /gap-analysis — ตรวจ SQL + Gap Analysis (G1, G2) · ตอบ Q Schema qualification',
    '/inputs (ของครบ) -> /gen-export -> Smart Import (ครั้งเดียว) -> gen_ddl -> Run Pack -> /read-results -> D1/D2 -> /cutover'
)
for ($i = 0; $i -lt $steps.Count; $i++) { Write-Host ("   {0}. {1}" -f ($i + 1), $steps[$i]) }
if ($DryRun) { Write-Host ''; Write-Warn 'DryRun — ยังไม่มีอะไรถูกเขียน' }

